import { test } from "node:test";
import assert from "node:assert/strict";
import { Histogram } from "../src/metrics/histogram.ts";
import { renderMetrics } from "../src/metrics/registry.ts";
import { createBidder, type BidRequest } from "../src/bidder/bidder.ts";

// Pricing engine fake: each call "takes" the next latency in the list on a fake clock.
function setup(latencies: number[], decide: (req: BidRequest) => number | null = () => 2.5) {
    const clock = { t: 0 };
    let call = 0;
    const pricing = {
        async price(req: BidRequest) {
            clock.t += latencies[call++ % latencies.length];
            if (req.id.startsWith("boom")) throw new Error("model server unavailable");
            return decide(req);
        },
    };
    return createBidder(pricing, () => clock.t);
}

const req = (id: string, floorCpm = 1): BidRequest => ({ id, exchange: "adx", floorCpm });

test("requests are counted by outcome", async () => {
    const bidder = setup([5], (r) => (r.id === "skip" ? null : r.id === "cheap" ? 0.5 : 2.5));
    for (const id of ["a", "b", "skip", "cheap"]) await bidder.handle(req(id));
    await assert.rejects(bidder.handle(req("boom-1")));
    assert.deepEqual(bidder.outcomes.entries(), [["below_floor", 1], ["bid", 2], ["error", 1], ["no_bid", 1]]);
});

test("latency sum and count cover every request, including failures", async () => {
    const bidder = setup([8, 30, 120]);
    await bidder.handle(req("a"));
    await bidder.handle(req("b"));
    await assert.rejects(bidder.handle(req("boom-2")));
    const snap = bidder.latency.snapshot();
    assert.deepEqual([snap.count, snap.sum], [3, 158]);
});

test("the /metrics histogram buckets are cumulative and +Inf equals the count", async () => {
    const bidder = setup([4, 9, 20, 40, 80, 300]);
    for (let i = 0; i < 6; i++) await bidder.handle(req(`r${i}`));
    const text = renderMetrics([], [bidder.latency]);
    const buckets = text.split("\n").filter((l) => l.startsWith("bidder_latency_ms_bucket"));
    console.log(buckets.join("\n"));
    assert.deepEqual(buckets, [
        'bidder_latency_ms_bucket{le="10"} 2',
        'bidder_latency_ms_bucket{le="25"} 3',
        'bidder_latency_ms_bucket{le="50"} 4',
        'bidder_latency_ms_bucket{le="100"} 5',
        'bidder_latency_ms_bucket{le="250"} 5',
        'bidder_latency_ms_bucket{le="+Inf"} 6',
    ]);
    assert.ok(text.includes("bidder_latency_ms_count 6\n"));
});

test("a fast bidder with one slow request is within the SLO", async () => {
    const bidder = setup([...new Array(199).fill(6), 400]);
    for (let i = 0; i < 200; i++) await bidder.handle(req(`r${i}`));
    assert.deepEqual(bidder.sloReport(), { withinSlo: 0.995, breaching: false });
});

test("the SLO alert fires when too many requests are slow", async () => {
    const bidder = setup([20, 20, 20, 150]);
    for (let i = 0; i < 100; i++) await bidder.handle(req(`r${i}`));
    assert.deepEqual(bidder.sloReport(), { withinSlo: 0.75, breaching: true });
});

test("a value exactly on a bucket bound lands in that bucket", () => {
    const h = new Histogram("t", "test", [10, 25]);
    h.observe(25);
    assert.deepEqual(h.snapshot().buckets.map((b) => b.count).slice(0, 2), [0, 1]);
});

test("bucket bounds must increase, and bad observations are ignored", () => {
    assert.throws(() => new Histogram("x", "x", [50, 10]), /strictly increasing/);
    assert.throws(() => new Histogram("x", "x", [10, 10]), /strictly increasing/);
    const h = new Histogram("x", "x", [10]);
    h.observe(-1);
    h.observe(Number.NaN);
    assert.deepEqual([h.snapshot().count, h.snapshot().sum], [0, 0]);
});
